import 'daily_vocab_item.dart';
import 'pocket_mission_curriculum_1_18.dart';

/// 📘 Curriculum Data for Days 39 to 50 (High-Stakes M&A, Crisis Diplomacy & Mid-Century Milestone)
class PocketCurriculum39To50 {
  static bool handles(int day) => day >= 39 && day <= 50;

  // --- 📖 3-PAGE DEEP LITERATURE STORIES ---
  static List<String> getStoryPages(int day) {
    switch (day) {
      case 39:
        return const [
          // PAGE 1: The Antitrust Inquest in Brussels (Page 1 of 3)
          'PAGE 1: THE BRUSSELS ANTITRUST INQUEST\n\n'
          'Before the European Antitrust Commission in Brussels, Lead Counsel Nadia defended a monumental forty-billion-dollar semiconductor merger between two global technology titans.\n\n'
          'Thirty adversarial regulators, backed by aggressive antitrust lawyers from rival corporations, fiercely claimed that the consolidated entity would monopolize next-generation silicon production and strangle open-source innovation in clean energy computing.\n\n'
          'Corporate executives behind Nadia urged her to fight aggressively and challenge the commission\'s jurisdiction. But Nadia understood that defensive bluster before European regulators is corporate suicide.\n\n'
          'She stepped to the microphone with absolute composure, deploying the supreme legal register of sophisticated conditional concession.',

          // PAGE 2: Sophisticated Conditional Concession & Guarantees (Page 2 of 3)
          'PAGE 2: CONDITIONAL CONCESSION & BINDING SAFEGUARDS\n\n'
          'Nadia disarmed the panel by granting their worst-case hypothesis upfront, only to counterweight it with unassailable structural guarantees:\n\n'
          '"Distinguished Commissioners, let us confront your central concern directly. Even if the consolidated entity were to achieve a forty percent market share across European data centers, existing open-source interoperability covenants prevent predatory pricing or exclusive hardware lock-in.\n\n'
          'Be that as it may, our client acknowledges the legitimate sensitivity of European cloud sovereignty. We therefore propose binding, enforceable behavioral remedies:\n\n'
          'First, establishing an open-access European patent pool; second, capping licensing royalties for ten full years; and third, submitting our manufacturing allocations to quarterly forensic audits conducted by an independent judicial overseer."',

          // PAGE 3: The Unanimous Approval & Commercial Precedent (Page 3 of 3)
          'PAGE 3: THE UNANIMOUS APPROVAL & PRECEDENT\n\n'
          'The hearing room fell silent. By conceding the hypothetical market share and preempting regulatory fears with enforceable behavioral covenants, Nadia deprived the commission of any legal justification to block the deal.\n\n'
          'By 6:00 PM, the European Commission issued a unanimous decision approving the forty-billion-dollar acquisition without demanding a single structural divestiture.\n\n'
          'The celebratory board members praised her brilliance. Nadia smiled and summarized the lesson for her corporate clients:\n\n'
          '"In corporate law and high-stakes negotiation, never deny an opponent\'s fear. Concede the condition, circumscribe the danger with ironclad guarantees, and you will command the outcome."',
        ];
      case 40:
        return const [
          // PAGE 1: The Midnight Naval Stand-off in the Pacific (Page 1 of 3)
          'PAGE 1: THE MIDNIGHT NAVAL CRISIS\n\n'
          'At 03:00 AM inside the subterranean Situation Room of the Global Defense Alliance, Strategic Intelligence Director Marcus faced fifteen sovereign military commanders amidst an explosive maritime standoff in the South China Sea.\n\n'
          'Hostile naval vessels had surrounded an allied civilian research vessel, and live radar tracking showed fighter jets scrambling on both sides of the maritime boundary.\n\n'
          'Inexperienced admirals urged immediate bellicose ultimatums: "We must order carrier strike groups to deploy full weapons-hot patrols immediately! If we don\'t show force, our deterrence is completely destroyed!"\n\n'
          'Marcus held up a hand. His baritone voice was quiet, icy, and unshaken by panic.',

          // PAGE 2: The Art of Calibrated Strategic Ambiguity (Page 2 of 3)
          'PAGE 2: CALIBRATED AMBIGUITY & STEALTH DETERRENCE\n\n'
          'Marcus laid out the razor\'s edge of geopolitical deterrence:\n\n'
          '"Gentlemen, observe the strategic dialectic: Were we to deploy carrier strike groups prematurely with aggressive public ultimatums, our adversaries would seize upon the spectacle as an unprovoked imperial escalation and mobilize their national reserves.\n\n'
          'Conversely, should our alliance remain passive and issue hollow platitudes, our regional treaty allies will perceive an irreversible erosion of sovereign deterrence.\n\n'
          'What we must project tonight is calibrated strategic ambiguity paired with undeniable physical capability: We quietly reposition two nuclear attack submarines into their littoral approach corridors while dispatching an unannounced diplomatic communique proposing neutral multilateral freedom-of-navigation talks in Singapore within twenty-four hours."',

          // PAGE 3: The Bloodless Dissipation & Power of Silence (Page 3 of 3)
          'PAGE 3: THE BLOODLESS DISSIPATION\n\n'
          'The order was executed immediately. Within two hours, enemy sonar detected the silent, immovable presence of the alliance submarines beneath their keel, even as the foreign ministry received the formal invitation to the Singapore summit.\n\n'
          'Deprived of a political pretext for war, and confronted by overwhelming subsurface readiness, the opposing fleet withdrew its blockade at dawn without firing a single missile.\n\n'
          'Marcus turned off the tactical screens and spoke to his junior intelligence officers:\n\n'
          '"In geopolitical statecraft, empty threats betray weakness. The greatest commanders speak with calibrated ambiguity and quiet discipline, letting silent capability do the work of war."',
        ];
      case 41:
        return const [
          // PAGE 1: The Newsroom at the British Sunday Chronicle (Page 1 of 3)
          'PAGE 1: FLEET STREET & THE LIFELESS EXPOSÉ\n\n'
