          'Maya had spent six months uncovering a massive procurement scandal involving the Secretary of Defense and a private defense contractor. Her data was irrefutable, but her draft read like a dry bureaucratic civil service memorandum.\n\n'
          '"Maya, my dear," Arthur said, gently setting the manuscript on his wooden desk, "truth without literary bite is dead on arrival. English investigative journalism does not drone like a government ledger; it breathes through understated wit, dry irony, and razor-sharp idiomatic bite.\n\n'
          'You write that the Minister was \'extremely worried\'. That is pedestrian. Let me show you how Fleet Street commands the English language."',

          // PAGE 2: Understated Wit & Calling a Spade a Spade (Page 2 of 3)
          'PAGE 2: THE FLEET STREET MASTERCLASS\n\n'
          'Arthur picked up a red pen and transformed Maya\'s dry lines into masterclass investigative literature:\n\n'
          '"Do not write that the Minister made vague excuses; write: \'To say the Secretary was mildly uncomfortable under cross-examination would be the British understatement of the century; his entire front bench sat on pins and needles as the leaked emails circulated.\'\n\n'
          'Do not write that civil servants worked late; write: \'Having burned the midnight oil for six grueling months, our investigators uncovered seven offshore holding accounts.\'\n\n'
          'Do not beat around the bush; call a spade a spade! When politicians disguise corruption as administrative oversight, unmask them with polished British irony!"\n\n'
          'Maya watched her dry notes spark into electric, gripping prose.',

          // PAGE 3: The National Press Award & The Power of Prose (Page 3 of 3)
          'PAGE 3: THE FRONT-PAGE SCOOP\n\n'
