          '"Indeed," Tariq whispered, holding up a certified digital document. "Yet, at 04:12 AM on the morning of November 4th, an encrypted command was dispatched from your personal laptop at your home residence, overriding security firewalls and transferring sixty million pounds to an offshore trust in Zurich.\n\n'
          'So I put it to you, Mr. Sterling: Were you being untruthful to federal regulators when you signed the audit disclosures, or are you being untruthful to this jury today?"',

