          'The jury returned a unanimous verdict of Not Guilty for the junior accountant within thirty minutes. Outside the courthouse, Tariq remarked to his pupil:\n\n'
          '"Cross-examination is not about bullying a witness; it is about building an inescapable syntactic trap where the only exit is the truth."',
