        return const [
          // PAGE 1: The Sand Hill Road Inquisition (Page 1 of 3)
          'PAGE 1: THE SAND HILL ROAD INQUISITION\n\n'
          'In a sleek, glass-enclosed boardroom on Sand Hill Road overlooking the eucalyptus hills of Silicon Valley, tech founder Lyra sat across from four partners of a tier-one venture capital consortium.\n\n'
          'Her enterprise software platform had reached fifteen million dollars in annual recurring revenue, but scaling globally required twenty-five million in Series B capital.\n\n'
          'The lead partner, a seasoned financier named Vance, slid an eighty-page term sheet across the walnut table with an aggressive smile:\n\n'
          '"We believe in your vision, Lyra. But given macroeconomic tightening, our term sheet includes 2X participating liquidation preferences, seniority overrides on future dividends, and four-year reset vesting on your founder shares. Take it or leave it."',

