          'If your partnership insists on seniority overrides and dividend preferences, we will structure an accelerated performance cliff: the moment our annualized revenue hits thirty million dollars, all preferred stock automatically converts to common equity, stripping away liquidation multipliers entirely."',

          // PAGE 3: The Sovereign Term Sheet Ratified (Page 3 of 3)
          'PAGE 3: THE SOVEREIGN FOUNDER COMPACT\n\n'
          'Vance exchanged stunned glances with his general partners. They had expected an intimidated technical founder; instead, they faced an executive fluent in corporate capitalization mechanics.\n\n'
