      case 44:
        return const [
          // PAGE 1: The Disputed Demarcation Line (Page 1 of 3)
          'PAGE 1: THE FRONTIER CRUCIBLE\n\n'
          'On a wind-swept demarcation line separating two warring sovereign states, Special Peace Envoy Nathan stood beside a single armored jeep. Snipers monitored the perimeter from limestone ridges, and heavy artillery concussions rattled the frozen earth.\n\n'
