          '"Your ceasefire is a Western illusion! Yesterday your peacekeepers allowed twenty of my scouts to be ambushed in the eastern pass. If our borders are not redrawn thirty kilometers south within thirty minutes, I will open fire on all southern civilian settlements!"',

