          'PAGE 2: THE FUTILITY RE-FRAME\n\n'
          'Nathan did not argue, reach for a weapon, or flinch before the loaded assault rifles. He looked Rostov directly in the eyes and applied surgical crisis mediation syntax:\n\n'
          '"General Rostov, I hear the profound, righteous grief and indignation in your voice, and I acknowledge without reservation that your battalion suffered grievous losses yesterday in the pass.\n\n'
          'Yet discharging rocket artillery into civilian villages this afternoon will not resurrect a single one of your fallen scouts; it will merely guarantee the total annihilation of your own family\'s towns tomorrow when the allied counter-battery strikes.\n\n'
