          'He realized that Nathan had offered him a pathway out of total catastrophe without sacrificing military honor. Rostov commanded his battery chiefs to stand down.\n\n'
          'Spreading the coordinate map across the dusty hood of the UN jeep, the two men inked the Demarcation Buffer Accord five minutes before the deadline expired. Nathan demonstrated that empathetic reframing and fearless moral composure can halt wars when weapons fail.',
