      case 45:
        return const [
          // PAGE 1: The Stockholm Nobel Forum (Page 1 of 3)
          'PAGE 1: THE STOCKHOLM CRUCIBLE\n\n'
          'Inside the Grand Hall of the Nobel Forum for Molecular Medicine in Stockholm, Dr. Sophia adjusted the lapel microphone before three thousand distinguished cardiologists, biophysicists, and international science correspondents.\n\n'
          'Her research institute had engineered a breakthrough epigenetic therapy capable of reversing cellular fibrosis in end-stage congestive heart failure.\n\n'
          'Her junior colleagues had warned her: "Stick to the raw biochemistry. Read the histone methyltransferase curves. Don\'t simplify; you will lose academic credibility."\n\n'
          'Sophia knew better. If she drowned the room in academic jargon, the world\'s venture philanthropists and global health ministers would never grasp the revolutionary human impact.',

          // PAGE 2: The Living Symphony Metaphor (Page 2 of 3)
          'PAGE 2: THE MOLECULAR MAESTRO\n\n'
          'Sophia stepped away from the podium and projected her voice across the acoustic ceiling:\n\n'
          '"For fifty years, medical dogma taught us to view human DNA as an unalterable stone tablet—a rigid, fatalistic script where genetic errors could only be mourned, never repaired.\n\n'
          'Tonight, I invite you to discard that stone tablet. Think of your genome instead as an expansive, magnificent orchestral score. In a failing heart, the musical notes remain completely intact; it is merely that the tempo markings have been smudged by age, stress, and chronic inflammation.\n\n'
          'Our epigenetic therapy does not rewrite the composer\'s manuscript; it acts as a molecular maestro, stepping onto the podium of the cell to restore pristine rhythm and harmony to the symphony of the human heart."',

          // PAGE 3: Standing Ovation & Fifty Global Trials (Page 3 of 3)
          'PAGE 3: HEALING THE PLANET\n\n'
          'On the massive screens behind her, clinical trial footage played: fifty terminal cardiac patients who had been unable to climb stairs six months ago were now walking briskly through mountain parks.\n\n'
          'The auditorium fell into awe-struck silence, followed by a thunderous, five-minute standing ovation from the international assembly. That evening, fifty sovereign medical research institutions committed to funding decentralized global trials.\n\n'
          'Sophia proved that trans-disciplinary analogies and poetic clarity do not cheapen complex science; they accelerate human healing across the earth.',
        ];
      case 46:
        return const [
          // PAGE 1: The Safety Board Hearing (Page 1 of 3)
          'PAGE 1: THE RUNWAY DISASTER INQUEST\n\n'
          'Under the harsh lights of the National Transportation Safety Board hearing room in Washington, aerospace conglomerate executives sat beside their legal defense teams.\n\n'
          'Three weeks earlier, two wide-body commercial airliners carrying six hundred passengers had narrowly avoided a catastrophic collision on a fog-choked runway in Chicago.\n\n'
          'The aircraft manufacturer had already launched a coordinated public relations campaign, leaking memos to blame two junior air traffic controllers who were working mandatory fourteen-hour shifts.\n\n'
