      case 47:
        return const [
          // PAGE 1: The Hardtalk Hot Seat (Page 1 of 3)
          'PAGE 1: THE BBC HARDTALK AMBUSH\n\n'
          'Beneath the blinding studio lamps of BBC Hardtalk in London, political reformer Elena sat opposite veteran inquisitor Jeremy, known worldwide for destroying guests through rapid-fire hostile cross-examination.\n\n'
          'The red on-air light flickered. Jeremy leaned across the desk with a vicious sneer:\n\n'
          '"Minister Elena, your sweeping urban housing reform is an unmitigated disaster and an egregious betrayal of low-income citizens! Isn\'t it true that your market-incentive deregulation has merely lined the pockets of billionaire property developers who funded your election campaign?"\n\n'
          'Ten million television viewers watched, waiting for Elena to stutter or explode in partisan outrage.',

          // PAGE 2: The Three-Part Pivot Executed (Page 2 of 3)
          'PAGE 2: THE THREE-PART PIVOT\n\n'
          'Elena maintained unbroken eye contact, rested her hands comfortably, and executed the classic Three-Part Media Pivot with razor-sharp precision:\n\n'
          '"Jeremy, that is a provocative narrative carefully designed to generate sensational television headlines; however, audited municipal census data tells a fundamentally different story:\n\n'
          'Over the past six months, forty-two thousand low-income families secured permanent, mortgage-free homes under statutory rent-to-own covenants. The paramount question confronting this broadcast is not whether private construction consortia participated, but whether working-class families have warm roofs over their heads—and on that definitive metric, the answer is an undeniable, measurable yes."',

          // PAGE 3: Narrative Sovereignty Achieved (Page 3 of 3)
          'PAGE 3: BROADCAST MASTERY\n\n'
          'Jeremy attempted three follow-up interruptions, but Elena anchored every counter-argument back to the audited municipal housing ledger with smiling, immovable poise.\n\n'
          'By the end of the thirty-minute broadcast, Jeremy conceded the debate on air, acknowledging that the reform had exceeded all public housing targets.\n\n'
