      case 48:
        return const [
          // PAGE 1: The Corporate Raid (Page 1 of 3)
          'PAGE 1: THE SHAREHOLDER SIEGE\n\n'
          'Inside the historic Great Hall of the London Stock Exchange, CEO Jonathan faced an extraordinary general meeting of five hundred institutional shareholders.\n\n'
          'A predatory offshore private-equity syndicate, having quietly acquired a twelve-percent activist stake in Jonathan\'s century-old high-speed rail engineering conglomerate, had launched a hostile proxy battle.\n\n'
          'Their lead raider, a ruthless asset-stripper named Sterling, had just finished an hour-long slide presentation arguing that European manufacturing was dead and demanding that the company\'s patent portfolio and factories be auctioned off to fund an immediate five-billion-pound dividend payout.',

          // PAGE 2: Rhetorical Fronting & Defiance (Page 2 of 3)
          'PAGE 2: THE LECTERN OF DEFIANCE\n\n'
          'Jonathan stepped to the center of the stage without notes, PowerPoint slides, or teleprompters. He looked directly at the pension fund trustees and delivered an electrifying masterclass in rhetorical fronting:\n\n'
          '"Ruinous though the past quarter\'s global supply chain disruptions appeared on spreadsheet balance sheets, sell off our foundational sovereign engineering heritage we will not!\n\n'
