          // PAGE 3: The 80% Supermajority Triumph (Page 3 of 3)
          'PAGE 3: THE SOVEREIGN VICTORY\n\n'
          'His rhetorical fire and moral clarity sent an electric surge through the assembly. The union pension fund representatives, who had entered the hall undecided, rose to their feet in unified applause.\n\n'
          'When the electronic proxy votes were tallied, eighty-two percent of voting shares rejected the hostile takeover and affirmed Jonathan\'s century-long industrial vision.\n\n'
          'The private equity raiders were forced to liquidate their stake at a loss. Jonathan demonstrated that rhetorical fronting and unyielding moral leadership defeat predatory boardroom syndicates.',
        ];
      case 49:
        return const [
          // PAGE 1: The Bonn Climate Deadlock (Page 1 of 3)
          'PAGE 1: THE BONN MIDNIGHT DEADLOCK\n\n'
          'At the World Conference Center in Bonn, Germany, delegates from one hundred and ninety-two sovereign nations sat exhausted at 3:00 AM on the final scheduled night of the UN Climate Secretariat.\n\n'
          'Deliberations on Article 6—the legal mechanism governing international carbon trading—had ground to a complete, bitter halt.\n\n'
          'Global South nations accused industrialized powers of "carbon colonialism," trading paper certificates without real emissions reductions. Industrialized nations refused to sign any agreement that exposed their corporations to arbitrary regulatory liability.\n\n'
          'Chief Environmental Negotiator Tara knew that only an airtight, legally enforceable treaty architecture could unlock consensus before the summit collapsed.',

          // PAGE 2: The Airtight Subjunctive Treaty (Page 2 of 3)
          'PAGE 2: EQUITABLE SUBJUNCTIVE ARCHITECTURE\n\n'
          'Tara took the plenary microphone and presented a newly drafted Article 6 text formulated around equitable subjunctive covenants:\n\n'
          '"Signatory sovereign states shall be legally permitted to transfer internationally mitigated carbon outcomes, provided that every transferred credit be verified through immutable, decentralized cryptographic registry audits.\n\n'
          'In the event that bilateral double-counting or fraudulent registry manipulation occur, sovereign emissions allocations shall immediately face mandatory twenty percent compounding forfeitures, and all market trading privileges shall be suspended until full restitution be made."',

          // PAGE 3: Consensus of 192 Nations (Page 3 of 3)
          'PAGE 3: THE BONN RULEBOOK RATIFIED\n\n'
          'Tara\'s formulation balanced sovereign trading rights with uncompromising, mathematically automated penalties. Developing nations were protected against fraud; industrialized buyers were protected against arbitrary fines.\n\n'
          'At 5:14 AM, the President of the COP brought down the ceremonial gavel: the Bonn Article 6 Rulebook was adopted unanimously by standing consensus without a single dissenting vote.\n\n'
          'Tara smiled as the hall erupted in exhausted cheers: "Precision legal English is not dry bureaucracy; it is the planetary scaffolding that preserves our shared biosphere for generations to come."',
