  // --- 📖 STORIES (Full Text) ---
  static String getStoryText(int day) {
    switch (day) {
      case 39:
        return 'Before the European Antitrust Commission in Brussels, Lead Counsel Nadia defended a monumental forty-billion-dollar semiconductor merger. Regulators fiercely questioned whether the acquisition would strangle competitive innovation in renewable computing. Rather than resorting to defensive bluster, Nadia deployed the register of sophisticated conditional concession: "Even if the consolidated entity were to achieve forty percent market share, existing open-source interoperability covenants prevent predatory pricing. Be that as it may, our client proposes binding behavioral remedies: establishing an open patent pool, capping licensing royalties for ten years, and submitting to quarterly forensic audits." Her precision in balancing legal concession with enforceable guarantees disarmed the commission\'s skepticism. By evening, the commission approved the transaction without structural divestitures. Nadia proved that mastery of conditional concession turns hostile regulatory inquisitions into approved commercial milestones.';
      case 40:
        return 'Inside the secure Situation Room of the Global Defense Alliance, Strategic Intelligence Director Marcus briefed fifteen sovereign military commanders amidst rising maritime tensions in the Pacific. Inexperienced analysts urged immediate bellicose declarations. Marcus counseled strategic restraint through the deliberate art of calibrated ambiguity: "Were we to deploy carrier strike groups prematurely, our adversaries would interpret the movement as an unprovoked escalation. Conversely, should we remain passive, our regional allies will perceive a total erosion of sovereign deterrence. What we must project today is unwavering capability paired with intentional diplomatic silence: quietly repositioning subsurface surveillance while proposing multilateral freedom-of-navigation talks." His nuanced linguistic balance denied adversaries a pretext for conflict while reassuring nervous allies. The maritime crisis dissipated without a single shot fired. Marcus demonstrated that in geopolitical statecraft, linguistic deterrence is mightier than raw military force.';
      case 41:
        return 'In the high-pressure newsroom of the British Sunday Chronicle, senior investigative editor Arthur mentored a talented cub reporter named Maya. Maya\'s articles were factually accurate but read like lifeless government bulletins. Arthur sat her down over tea and unpicked her prose: "English journalism, Maya, is animated by idiomatic irony, understated wit, and conversational bite. You don\'t write that the minister was very nervous; you say he was on pins and needles. You don\'t write that the negotiations succeeded; you say they saw eye to eye after burning the midnight oil. Don\'t beat around the bush; call a spade a spade, but do it with dry British irony." Following his guidance, Maya injected subtle idiomatic flair and sharp British understatement into her front-page scoop. Her piece won the National Press Award that winter. Maya proved that idiomatic irony and understated wit transform dry reporting into electrifying literature.';
      case 42:
        return 'In the Central Criminal Court of England and Wales, Senior Barrister Tariq cross-examined a key prosecution witness in a multi-million-pound corporate fraud trial. The witness had testified with polished confidence during direct examination, painting the defendant as a reckless embezzler. Tariq knew that only surgical syntactic pacing could dismantle the witness\'s rehearsed facade: "You testified earlier that you were entirely unaware of the offshore transactions. Yet, on November 4th, an encrypted communication was dispatched from your personal terminal authorizing the transfer. Were you being untruthful then, or are you being untruthful to this jury today?" When the witness stuttered, Tariq paused, letting the silence magnify the contradiction. Caught between his own conflicting records, the witness admitted to forging the audit trail. Tariq demonstrated that forensic pacing and sharp dilemma formulation dismantle falsehood under oath.';
      case 43:
        return 'In a glass-enclosed executive boardroom overlooking Silicon Valley, venture founder Lyra sat across from an aggressive tier-one investment consortium to finalize her Series B term sheet. The lead investor attempted to insert punitive 2X liquidation preferences and restrictive founder-vesting provisions. Lyra did not lose her temper; she leaned forward and navigated the commercial clauses with masterclass negotiation acumen: "We appreciate your capital commitment; however, non-participating 1X preferred liquidation is our unwavering standard. If your firm insists on seniority overrides, we will structure an accelerated milestone cliff that converts preferred equity to common stock upon achieving thirty million in annualized gross revenue." Disarmed by her mastery of complex venture terminology and calm commercial boundaries, the venture partners withdrew every punitive covenant. Lyra proved that executive fluency in venture capital contracts protects founder sovereignty.';
      case 44:
        return 'On the neutral border demarcation line between two warring sovereign states, Special Envoy Nathan led emergency ceasefire negotiations. Snipers watched from surrounding hills, and artillery shells echoed in the distance. When the opposing warlord threatened to resume bombardment within thirty minutes, Nathan did not trade insults or show panic. Instead, he deployed high-stakes crisis de-escalation: "Commander, I hear your righteous anger regarding yesterday\'s border skirmish, and I recognize that your battalion suffered casualties. But firing artillery today will not resurrect your fallen soldiers; it will simply guarantee the destruction of your civilian villages tomorrow. What we both seek is an internationally monitored buffer corridor that preserves your territorial honor. Let our observers deploy before the noon hour." His steady moral authority broke the warlord\'s combative momentum. The ceasefire was signed on the hood of a peacekeeping vehicle. Nathan showed that words of empathetic reason stop wars.';
      case 45:
        return 'At the Nobel Forum for Molecular Medicine in Stockholm, Dr. Sophia addressed three thousand physicians, investors, and science journalists. Her team had engineered an epigenetic therapy capable of reversing cardiac cell degeneration. Rather than burying the audience under impenetrable biochemical jargon like \'histone acetyltransferase downregulation\', Sophia commanded the hall with the poetic power of functional analogies: "Think of your DNA not as a rigid stone tablet, but as an expansive orchestral score. In failing hearts, the musical notes remain intact, but the tempo markings have been smudged by age and disease. Our epigenetic therapy acts as a molecular maestro, restoring pristine rhythm to the symphony of the heart." The auditorium held its breath as clinical trial videos played, showing patients walking again. The keynote resulted in fifty global research partnerships. Sophia showed that translating science into vivid English accelerates healing across the world.';
      case 46:
        return 'Before the National Transportation Safety Board hearing, Chief Aeronautical Investigator Daniel presented the final verdict on a near-fatal commercial jetliner collision. Major aerospace manufacturers had attempted to blame junior air traffic controllers. Daniel stood before the packed auditorium and delivered an uncompromising masterclass in systems-level forensic passive syntax: "It was not human pilot error that precipitated this runway crisis; it was the failure of automated ground-radar telemetry during heavy precipitation. Warning signals were suppressed by legacy software protocols. It is formally mandated that dual-channel fail-safe radar be installed across all international hubs within ninety days." By directing focus to systemic engineering failures rather than convenient scapegoats, his report revolutionized global aviation safety. Daniel proved that forensic passive syntax speaks truth to corporate power.';
      case 47:
        return 'Under the merciless studio spotlights of BBC Hardtalk, political strategist Elena faced veteran inquisitor Jeremy, renowned for shredding politicians to pieces. Jeremy fired a blistering trap question: "Isn\'t your administration\'s housing reform an egregious betrayal of low-income families that has made your campaign donors fabulously wealthy?" Elena did not look away, nor did she erupt in anger. She looked straight into the camera and applied the classic Three-Part Pivot: "Jeremy, that is a provocative narrative designed for television headlines; however, the audited census records prove that forty thousand low-income families secured mortgage-free homes this quarter alone. The question isn\'t whether private capital was utilized; the real question is whether working families have roofs over their heads, and the answer is an undeniable yes." Her masterclass in narrative sovereignty silenced the interviewer and trended globally. Elena proved that verbal composure conquers hostile media traps.';
      case 48:
        return 'In the towering headquarters of a FTSE-100 industrial conglomerate in London, CEO Jonathan faced an emergency extraordinary general meeting convened by aggressive activist short-sellers attempting a hostile boardroom takeover. The activists presented slick slide decks predicting corporate insolvency. Jonathan stepped to the podium without notes, commanding the room with rhetorical fronting and counter-cyclical vision: "Ruinous though the past quarter\'s supply shock appeared, sell off our foundational industrial assets we will not. Front and center stands our fifty-year commitment to sovereign engineering excellence. What these activists propose is the strip-mining of our future for short-term dividends; what we propose is the electrification of Europe\'s high-speed rail network." His electrifying defiance rallied institutional pension funds to his side. The takeover bid was defeated by an eighty-percent shareholder majority. Jonathan proved that rhetorical fire and moral clarity defeat boardroom predator syndicates.';
      case 49:
        return 'At the United Nations Climate Secretariat in Bonn, Chief Environmental Negotiator Tara drafted the legal architecture for the Article 6 International Carbon Credit Treaty. Developing nations feared green-colonialism, while industrialized states demanded strict emissions offsets. Tara resolved the ideological impasse through the precision of equitable conditional clauses: "Signatory states shall be permitted to transfer internationally mitigated outcomes, provided that every credit be verified through decentralized cryptographic audits. In the event that double-counting occurs, sovereign quota allotments will face immediate twenty percent deductions." Her airtight, equitable formulations satisfied both environmental purity and economic practicality. One hundred and ninety-two sovereign states adopted the Bonn Rulebook by consensus. Tara showed that bilingual English mastery is the cornerstone of planetary environmental statecraft.';
      case 50:
        return 'At the Grand Sovereign Parliament in London, on the historic fiftieth milestone day of the National Renewal Summit, Statesman Kaelen rose to deliver the Mid-Century Sovereign Keynote before the gathered heads of five hundred world institutions. Halfway through the 90-day transformation journey, Kaelen stood as living proof of total English fluency. He synthesized every oratorical weapon mastered across fifty days: formal subjunctives, negative inversions, past modal deductions, classical chiasmus, and high-EQ empathy. "We stand today not at the midpoint of our journey, but at the apex of our awakening. We have learned that language is not a fence to divide us, but a bridge to unite us; not an instrument of domination, but an engine of liberation. Let history record that on Day 50, we chose not silence, but voice; not hesitation, but eloquence; not fear, but sovereign leadership." The thunderous applause of the assembly shook the vaulted halls. Kaelen reached the summit of mid-century linguistic mastery, proving that fifty days of disciplined dedication transforms human potential into timeless leadership.';
      default:
        return '';
    }
  }

