  // --- 🌐 MULTILINGUAL GRAMMAR EXPLANATIONS ---
  static String getGrammarRuleExplanation(int day, String lang) {
    final l = lang.toLowerCase();
    switch (day) {
      case 39:
        if (l == 'malayalam') {
          return 'Conditional Concession (വ്യവസ്ഥാപിത വിട്ടുവീഴ്ച): കോർപ്പറേറ്റ് തർക്കങ്ങളിലും റെഗുലേറ്ററി വിസ്താരങ്ങളിലും എതിരാളികളുടെ വാദത്തിന്റെ ഒരു ഭാഗം അംഗീകരിച്ചുകൊണ്ട് തന്നെ നമ്മുടെ വ്യവസ്ഥകൾ ഉറപ്പിച്ചു നിർത്തുന്ന ശൈലി:\n• "Even if the merged entity were to achieve 40% market share, open-source covenants prevent predatory pricing."\n• "Be that as it may, we propose binding behavioral remedies."';
        } else if (l == 'tamil') {
          return 'Conditional Concession: ஒழுங்குமுறை விசாரணைகளில் எதிர்தரப்பு வாதத்தின் ஒரு பகுதியை ஏற்றுக்கொண்டு நமது நிபந்தனைகளை உறுதிப்படுத்தும் நயவுரை.';
        } else if (l == 'hindi') {
          return 'Conditional Concession: नियामक जांच और कॉर्पोरेट वार्ता में विपक्षी तर्क को आंशिक रूप से स्वीकार करते हुए अपनी शर्तें मनवाने की कला।';
        } else if (l == 'telugu') {
          return 'Conditional Concession: నియంత్రణ సంస్థల విచారణల్లో ప్రత్యర్థుల వాదనను పాక్షికంగా అంగీకరిస్తూనే మన షరతులను బలంగా నిలబెట్టే శైలి.';
        } else if (l == 'kannada') {
          return 'Conditional Concession: ನಿಯಂತ್ರಕ ವಿಚಾರಣೆಗಳಲ್ಲಿ ಎದುರಾಳಿಯ ವಾದವನ್ನು ಭಾಗಶಃ ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಲೇ ನಮ್ಮ ಷರತ್ತುಗಳನ್ನು ದೃಢವಾಗಿ ಮಂಡಿಸುವ ಕಲೆ.';
        }
        return 'Conditional Concession grants hypothetical ground ("Even if [X] were to occur...") while immediately securing decisive legal guarantees ("...covenants prevent predatory pricing").';

      case 40:
        if (l == 'malayalam') {
          return 'Calibrated Ambiguity (തന്ത്രപരമായ അവ്യക്തത): അന്താരാഷ്ട്ര നയതന്ത്രത്തിലും പ്രതിരോധ രംഗത്തും യുദ്ധം ഒഴിവാക്കാനും അതേസമയം സ്വന്തം ശക്തി തെളിയിക്കാനുമുള്ള ശൈലി:\n• "Were we to deploy carrier groups prematurely, adversaries would claim provocation."\n• "What we must project is capability paired with intentional diplomatic silence."';
        } else if (l == 'tamil') {
