        } else if (l == 'kannada') {
          return 'Calibrated Ambiguity: ಅಂತರರಾಷ್ಟ್ರೀಯ ರಾಜತಾಂತ್ರಿಕತೆಯಲ್ಲಿ ಯುದ್ಧವನ್ನು ತಪ್ಪಿಸುತ್ತಲೇ ನಮ್ಮ ಶಕ್ತಿಯನ್ನು ತೋರಿಸುವ ಚಾಣಾಕ್ಷ ಭಾಷಾ ಶೈಲಿ.';
