        } else if (l == 'hindi') {
          return 'Idiomatic Irony: सीधे शब्दों के स्थान पर सूक्ष्म व्यंग्य, मुहावरों और गरिमापूर्ण भाषा का प्रयोग करने की ब्रिटिश शैली।';
        } else if (l == 'telugu') {
