  // --- 💡 STORY SUMMARIES ---
  static String getStorySummary(int day, String lang) {
    final l = lang.toLowerCase();
    switch (day) {
      case 39:
        if (l == 'tamil') return '💡 நீதி: "சட்ட விவாதங்களில் தந்திரமான இணக்கமும் தெளிவான உத்தரவாதங்களுமே மிகப்பெரிய வெற்றிகளைத் தரும்."';
        if (l == 'hindi') return '💡 सीख: "नियामक लड़ाइयों में रणनीतिक रियायत और ठोस कानूनी गारंटी ही ऐतिहासिक विजय दिलाती है।"';
        if (l == 'telugu') return '💡 నీతి: "చట్టపరమైన చర్చల్లో వ్యూహాత్మక సర్దుబాటు మరియు ఖచ్చితమైన హామీలు మాత్రమే ఘనవిజయాన్ని అందిస్తాయి."';
        if (l == 'kannada') return '💡 ನೀತಿ: "ಕಾನೂನು ಚರ್ಚೆಗಳಲ್ಲಿ ಚಾಣಾಕ್ಷ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ಸ್ಪಷ್ಟ ಭರವಸೆಗಳೇ ದೊಡ್ಡ ಯಶಸ್ಸನ್ನು ತಂದುಕೊಡುತ್ತವೆ."';
        return '💡 സന്ദേശം: "തന്ത്രപരമായ വിട്ടുവീഴ്ചകളും വ്യക്തമായ ഉറപ്പുകളും ഏത് കടുത്ത നിയമ യുദ്ധങ്ങളിലും നമുക്ക് വിജയം സമ്മാനിക്കും."';

      case 40:
        if (l == 'tamil') return '💡 நீதி: "ஆயுதங்களின் சத்தத்தை விட அமைதியான ராஜதந்திர மொழியே பேரழிவுகளைத் தடுக்கிறது."';
        if (l == 'hindi') return '💡 सीख: "हथियारों के शोर से अधिक शक्तिशाली शांत और संतुलित कूटनीतिक भाषा होती है जो युद्ध टालती है।"';
        if (l == 'telugu') return '💡 నీతి: "ఆయుధాల మోత కంటే ప్రశాంతమైన దౌత్యపరమైన మాటే మహా వినాశనాన్ని ఆపగలదు."';
        if (l == 'kannada') return '💡 ನೀತಿ: "ಶಸ್ತ್ರಾಸ್ತ್ರಗಳ ಅಬ್ಬರಕ್ಕಿಂತ ಶಾಂತ ರಾಜತಾಂತ್ರಿಕ ಭಾಷೆಯೇ ಮಹಾಯುದ್ಧಗಳನ್ನು ತಡೆಯಬಲ್ಲದು."';
        return '💡 സന്ദേശം: "ആയുധങ്ങളുടെ ശബ്ദത്തേക്കാൾ ശക്തമായ നയതന്ത്ര സംഭാഷണങ്ങൾക്കാണ് ലോകത്തെ വിനാശത്തിൽ നിന്ന് രക്ഷിക്കാൻ കഴിയുക."';

