      case 42:
        if (l == 'tamil') return '💡 நீதி: "ஆவணங்களின் துல்லியமும் சரியான மௌனமுமே பொய்யை சுக்குநூறாக உடைத்தெறியும்."';
        if (l == 'hindi') return '💡 सीख: "अकाट्य प्रमाण और सही समय पर मौन ही सबसे बड़े झूठ को चकनाचूर कर देते हैं।"';
        if (l == 'telugu') return '💡 నీతి: "తిరుగులేని ఆధారాలు మరియు సమయోచిత నిశ్శబ్దమే అబద్ధాలను పటాపంచలు చేస్తాయి."';
        if (l == 'kannada') return '💡 ನೀತಿ: "ನಿಖರ ಪುರಾವೆಗಳು ಮತ್ತು ಮೌನವೇ ಮಹಾನ್ ಸುಳ್ಳನ್ನು ಪುಡಿಪುಡಿ ಮಾಡುತ್ತವೆ."';
        return '💡 സന്ദേശം: "കൃത്യമായ തെളിവുകളും സന്ദർഭോചിതമായ നിശബ്ദതയും ഏതൊരു കള്ളത്തെയും പൂർണ്ണമായി തകർത്തെറിയും."';

      case 43:
        if (l == 'tamil') return '💡 நீதி: "வணிக ஒப்பந்தங்களில் தெளிவான அறிவும் உறுதியான நிலைப்பாடுமே சுயாட்சியைப் பாதுகாக்கும்."';
        if (l == 'hindi') return '💡 सीख: "व्यापारिक अनुबंधों में स्पष्ट ज्ञान और दृढ़ संकल्प ही आपकी संप्रभुता की रक्षा करते हैं।"';
        if (l == 'telugu') return '💡 నీతి: "వ్యాపార ఒప్పందాలలో స్పష్టమైన అవగాహన మరియు దృఢమైన వైఖరి మాత్రమే మన హక్కులను కాపాడతాయి."';
        if (l == 'kannada') return '💡 ನೀತಿ: "ವಾಣಿಜ್ಯ ಒಪ್ಪಂದಗಳಲ್ಲಿ ನಿಖರ ಜ್ಞಾನ ಮತ್ತು ದೃಢ ನಿಲುವೇ ನಮ್ಮ ಸ್ವಾಯತ್ತತೆಯನ್ನು ರಕ್ಷಿಸುತ್ತದೆ."';
        return '💡 സന്ദേശം: "കരാറുകളിലെ കൃത്യമായ അറിവും പതറാത്ത നിലപാടുകളുമാണ് ഒരു സംരംഭകന്റെ സ്വാതന്ത്ര്യം സംരക്ഷിക്കുന്നത്."';

