            objects: ['subject to rigorous quarterly inspections by an independent European trustee, in default whereof the clearance shall be summarily nullified', 'subject to strict biometric data siloing, in default whereof severe antitrust sanctions shall be executed immediately'],
          ),
          SentencePatternItem(
            formula: 'Only on condition that [Non-Negotiable Concession] will [Regulatory Authority] abstain from [Punitive Enforcement Action]',
