            masterSentences: [
              'Only on condition that the platform surrender its proprietary search ranking algorithm will the Commission abstain from initiating formal cartel prosecution.',
              'Only on condition that the telecommunications conglomerate unbundle regional fiber networks will the antitrust authorities abstain from blocking the acquisition.',
