            subjects: ['Only on condition that the global software monopoly dismantle its discriminatory application bundling within forty-five days', 'Only on condition that the transnational consortium surrender seventy airport take-off slots at Heathrow and Charles de Gaulle'],
            verbs: ['will the European Commission abstain from imposing twenty-billion-euro turnover penalties', 'will the antitrust ministry abstain from referring the transaction to criminal competition tribunals'],
            objects: ['and permit continued single-market operation', 'under the expedited divestiture framework', 'with full restoration of competitive parity'],
          ),
          SentencePatternItem(
            formula: 'Should [Party] fail to [Divestment Schedule], [Penalty Mechanism] shall attach automatically without further notice',
            explanation: 'നിശ്ചിത സമയപരിധിക്കുള്ളിൽ കടമ നിർവഹിച്ചില്ലെങ്കിൽ ശിക്ഷാ നടപടികൾ യാതൊരു മുന്നറിയിപ്പുമില്ലാതെ സ്വമേധയാ പ്രാബല്യത്തിൽ വരുമെന്ന് മുന്നറിയിപ്പ് നൽകാൻ (Automatic Inversion Sanction).',
            masterSentences: [
