  // --- 🗣️ PRONUNCIATION CLINIC (Minimal Pairs & Phonetic Mechanics) ---
  static PronunciationClinicItem getPronunciationClinic(int day) {
    switch (day) {
      case 39:
        return const PronunciationClinicItem(
          focusSound: 'Legalistic Proviso Precision & Sibilant Articulation (/prəˈvaɪ.dɪd ðæt/, /ˈsʌb.dʒɪkt tuː/)',
          mouthPositionTip: '🏛️ ബ്രസ്സൽസ് ആന്റിട്രസ്റ്റ് റെഗുലേറ്ററി ശൈലി: 40 ബില്യൺ ഡോളറിന്റെ ലയന ചർച്ചകളിൽ സംസാരിക്കുമ്പോൾ വികാരമല്ല, നിയമത്തിന്റെ തണുത്ത കൃത്യതയാണ് പ്രകടമാകേണ്ടത്. വായുടെ മുൻഭാഗത്ത് നാവിന്റെ അഗ്രം ഉപയോഗിച്ച് വ്യക്തമായി വാക്കുകൾ ചെത്തിമിനുക്കുക:\n• "Proviso" (/prəˈvaɪ.zəʊ/) - \'v\' ചുണ്ടിൽ പല്ലമർത്തി പറയുക\n• "Divestiture" (/daɪˈves.tɪ.tʃər/) - രണ്ടാമത്തെ സിലബസിൽ സ്ട്രെസ്സ്\n• "In default whereof" (/ɪn dɪˈfɔːlt weərˈɒv/) - ആർക്കെയ്ക് ലീഗൽ പദമായതിനാൽ ശബ്ദത്തിൽ പൂർണ്ണ ആധികാരികത വേണം.',
          minimalPairs: [
            {'wordA': 'Proviso (വ്യവസ്ഥ/ഉപാധി)', 'wordB': 'Provision (സഹായം/വ്യവസ്ഥ)', 'contrast': '/prəˈvaɪ.zəʊ/ vs /prəˈvɪʒ.ən/'},
            {'wordA': 'Divest (ഓഹരി/സ്വത്ത് വിൽക്കുക)', 'wordB': 'Digest (ദഹിപ്പിക്കുക/ഗ്രഹിക്കുക)', 'contrast': '/daɪˈvest/ vs /daɪˈdʒest/'},
            {'wordA': 'Cartel (വ്യാപാര കുത്തക സഖ്യം)', 'wordB': 'Curtail (ചുരുക്കുക/തടയുക)', 'contrast': '/kɑːˈtel/ vs /kəˈteɪl/'},
