          minimalPairs: [
            {'wordA': 'Unvarnished (പച്ചയായ/മിനുക്കാത്ത)', 'wordB': 'Unvanquished (തോൽപ്പിക്കപ്പെടാത്ത)', 'contrast': '/ʌnˈvɑː.nɪʃt/ vs /ʌnˈvæŋ.kwɪʃt/'},
            {'wordA': 'Litotes (അണ്ടർസ്റ്റേറ്റ്മെന്റ് ആലങ്കാരിക പ്രയോഗം)', 'wordB': 'Lethal (മാരകമായ)', 'contrast': '/ˈlaɪ.tə.tiːz/ vs /ˈliː.θəl/'},
