            {'wordA': 'Incompetence (അപ്രാപ്തി/കഴിവുകേട്)', 'wordB': 'Incontinence (നിയന്ത്രണമില്ലായ്മ)', 'contrast': '/ɪnˈkɒm.pɪ.təns/ vs /ɪnˈkɒn.tɪ.nəns/'},
            {'wordA': 'Concede (സമ്മതിക്കുക/വിട്ടുകൊടുക്കുക)', 'wordB': 'Conceal (മറച്ചുവെക്കുക)', 'contrast': '/kənˈsiːd/ vs /kənˈsiːl/'},
