  // --- ⚡ SOVEREIGN FLUENCY SHORTCUT / KURUKKUVAZHI (Mnemonic Hacks) ---
  static FluencyShortcutItem getFluencyShortcut(int day) {
    switch (day) {
      case 39:
        return const FluencyShortcutItem(
          title: 'The Antitrust Proviso Triad: Provided That, Subject To, In Default Whereof',
          malyalamHeading: '⚡ കുറുക്കുവഴി 39: വലിയ ഉടമ്പടികളിലോ ബിസിനസ്സ് അനുമതികളിലോ കർശന ഉപാധികൾ വെച്ച് സുരക്ഷിതരാകാൻ',
          ruleSummary: 'ഒരു അനുമതി നൽകുമ്പോൾ 3 ഘട്ടങ്ങൾ പാലിക്കുക: 1. "Granted, provided that [Mandatory Action]..." (നിർബന്ധിത വ്യവസ്ഥ), 2. "...subject to [Inspection]..." (തുടർ മേൽനോട്ടം), 3. "...in default whereof [Sanction]!" (ലംഘിച്ചാൽ കടുത്ത ശിക്ഷ).',
          quickHack: '💡 "Provided that + Subject to + In default whereof". ഈ മൂന്ന് ലീഗൽ പ്രൊവൈസോകൾ ഒന്നിച്ച് ചേർത്താൽ ഒരു അന്താരാഷ്ട്ര ട്രിബ്യൂണലിനും നിങ്ങളുടെ കരാർ റദ്ദാക്കാനാവില്ല!',
          examples: [
            'Approved, provided that assets are divested within 90 days. (90 ദിവസത്തിനകം ആസ്തികൾ വിൽക്കുമെന്ന വ്യവസ്ഥയിൽ അംഗീകരിക്കുന്നു.)',
            'Subject to quarterly audit, in default whereof approval is revoked. (ഓഡിറ്റിംഗിന് വിധേയമായി, ലംഘിച്ചാൽ അംഗീകാരം റദ്ദാക്കും.)',
          ],
        );

      case 40:
        return const FluencyShortcutItem(
