          malyalamHeading: '⚡ കുറുക്കുവഴി 47: ചാനൽ ചർച്ചകളിലും പ്രസ് മീറ്റുകളിലും കുറ്റപ്പെടുത്തുന്ന മാധ്യമപ്രവർത്തകരെ നിഷ്പ്രഭരാക്കാൻ',
